/// The current counter value of one (target, metric) row; the missing
/// row reads 0. Like the service-face counters, the lookup carries no
/// tenant filter (the interaction domain's rows are stamped but not
/// tenant-scoped).
pub async fn counter_of<C: ConnectionTrait>(
    db: &C,
    target_type: i16,
    target_id: i64,
    metric: i16,
) -> StatusResult<i64> {
    Ok(counter_row(db, target_type, target_id, metric)
        .await?
        .and_then(|r| r.count)
        .unwrap_or(0))
}
/// The counter upsert/decrement (the reference's adjustCounterRow): the
/// missing row is created only for a positive delta; a row pushed to 0
/// or below is deleted.
pub async fn adjust_counter<C: ConnectionTrait>(
    db: &C,
    tenant_id: i64,
    target_type: i16,
    target_id: i64,
    metric: i16,
    delta: i64,
) -> StatusResult<()> {
    let Some(row) = counter_row(db, target_type, target_id, metric).await? else {
        if delta <= 0 {
            // No row to decrement — the idempotent no-op.
            return Ok(());
        }
        interaction_counters::ActiveModel {
            tenant_id: Set(Some(tenant_id)),
            target_type: Set(Some(target_type)),
            target_id: Set(Some(target_id)),
            metric: Set(Some(metric)),
            count: Set(Some(delta)),
            created_at: Set(Some(store::now())),
            ..Default::default()
        }
        .insert(db)
        .await
        .map_err(db_status)?;
        return Ok(());
    };
    let next = row.count.unwrap_or(0) + delta;
    if next <= 0 {
        // The zeroed count drops the row (the reference's归0删行 branch).
        interaction_counters::Entity::delete_by_id(row.id)
            .exec(db)
            .await
            .map_err(db_status)?;
        return Ok(());
    }
    let mut a: interaction_counters::ActiveModel = row.into();
    a.count = Set(Some(next));
    a.update(db).await.map_err(db_status)?;
    Ok(())
}
async fn counter_row<C: ConnectionTrait>(
    db: &C,
    target_type: i16,
    target_id: i64,
    metric: i16,
) -> StatusResult<Option<interaction_counters::Model>> {
    interaction_counters::Entity::find()
        .filter(
            sea_orm::Condition::all()
                .add(interaction_counters::Column::TargetType.eq(target_type))
                .add(interaction_counters::Column::TargetId.eq(target_id))
                .add(interaction_counters::Column::Metric.eq(metric)),
        )
        .one(db)
        .await
        .map_err(db_status)
}
/// The ledger truth for one (target, metric) — the recount source of
/// ResetCounter. LIKE off the post/comment like ledgers, WATCH off the
/// post watches.
pub async fn count_ledger<C: ConnectionTrait>(
    db: &C,
    metric: i16,
    target_type: i16,
    target_id: i64,
) -> StatusResult<u64> {
    match (metric, target_type) {
        (1, 2) => comment_likes_target_count(db, target_id).await,
        (2, _) => post_watches_target_count(db, target_id).await,
        _ => post_likes_target_count(db, target_id).await,
    }
}
