/// The per-target ledger wipes of PurgeTargetInteractions, returning the
/// rows removed.
pub async fn delete_post_likes_of_post<C: ConnectionTrait>(
    db: &C,
    post_id: i64,
) -> StatusResult<u64> {
    let res = post_likes::Entity::delete_many()
        .filter(post_likes::Column::PostId.eq(post_id))
        .exec(db)
        .await
        .map_err(db_status)?;
    Ok(res.rows_affected)
}
