/// The target ids of a user's ledger rows (the PurgeUserInteractions
/// scan; each id rolls its counter back one step before the wipe).
pub async fn post_like_targets_of_user<C: ConnectionTrait>(
    db: &C,
    user_id: i64,
) -> StatusResult<Vec<i64>> {
    Ok(post_likes::Entity::find()
        .filter(post_likes::Column::UserId.eq(user_id))
        .all(db)
        .await
        .map_err(db_status)?
        .into_iter()
        .filter_map(|r| r.post_id)
        .collect())
}
